"""Factory functions for deep test data. Plain functions, no library."""
from itertools import count

from models import Address, Customer, LineItem, Order

_ids = {
    "address": count(1),
    "customer": count(1),
    "order": count(1),
}


def make_address(**over):
    defaults = dict(
        street=f"{next(_ids['address'])} Test St",
        city="Springfield",
        country="US",
    )
    return Address(**{**defaults, **over})


def make_customer(**over):
    cid = next(_ids["customer"])
    defaults = dict(
        id=cid,
        name="Jane Doe",
        email=f"jane.doe.{cid}@example.com",
        shipping=make_address(),
        billing=None,
    )
    kwargs = {**defaults, **over}
    if "billing" not in over:
        # billing is a COPY of shipping unless explicitly given
        kwargs["billing"] = make_address(
            **{
                f: getattr(kwargs["shipping"], f)
                for f in ("street", "city", "country")
            }
        )
    del kwargs["billing"] if False else None  # no-op; billing set above
    return Customer(**kwargs)


def make_line_item(**over):
    defaults = dict(sku="SKU-001", qty=1, unit_cents=1000)
    return LineItem(**{**defaults, **over})


def make_order(**over):
    defaults = dict(
        id=next(_ids["order"]),
        customer=make_customer(),
        items=[],
        status="new",
    )
    return Order(**{**defaults, **over})

