from tests.factories import make_line_item, make_order


def test_total_cents_mixed_items():
    order = make_order(
        items=[
            make_line_item(sku="A", qty=2, unit_cents=1000),  # 2000
            make_line_item(sku="B", qty=3, unit_cents=250),   # 750
            make_line_item(sku="C", qty=1, unit_cents=9999),  # 9999
        ]
    )
    assert order.total_cents() == 12749


def test_empty_order_totals_zero():
    assert make_order().total_cents() == 0
